import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/M-S-HDS-CF6.onaQ35vF.js";import{_ as o,o as s,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const k=JSON.parse('{"title":"CareLink follower","description":"","frontmatter":{},"headers":[],"relativePath":"install/carelinkfollow.md","filePath":"install/carelinkfollow.md"}'),l={name:"install/carelinkfollow.md"};function p(d,i,m,c,u,f){return s(),n("div",null,[...i[0]||(i[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   CareLink Follower</p></div><br><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Carelink servers are subject to frequent modifications that might break the feature.<br><strong>Use the <a href="./download.html#pre-release">latest pre-release</a> in case of issues.</strong><br> Consider using <a href="./companion.html">Companion app</a> on the master phone and xDrip <a href="./xdripfollower.html">Sync</a> or Nightscout to share data.<br> The CarePartner app authentication is valid for 1 week, thus even if xDrip is unable to connect to CareLink for a few days (for example due to the lack of internet connection), it will be able to renew the login (refresh the token) automatically in the background after it can connect to CareLink again without needing to log in again manually using the browser. The user account restriction applies to this authentication process as well:<br><strong>a dedicated follower account must be used for xDrip, you cannot use the same follower for other apps or phones.</strong></p></div><br><p>This also works for a standalone Simplera CGM (used without a linked pump) uploading to CareLink.</p><p>Select the country in which you registered your CareLink user.</p><div class="admonition xdripitem"><p class="admonition-title">CareLink Country</p><p> Select your CareLink country</p></div><p>Set patient username if using a care partner account with multiple patients.</p><div class="admonition xdripitem"><p class="admonition-title">CareLink Patient Username</p><p> CareLink patient username (optional)</p></div><p>xDrip will open the CareLink authentication web site, enter your credentials to log in.</p><div class="admonition xdripitem"><p class="admonition-title">Login</p><p> Login with browser</p></div><p>Grace period is an additional waiting time after receiving last reading + 5 minutes.<br> Used to avoid server lock if xDrip performs too frequent requests.</p><div class="admonition xdripitem"><p class="admonition-title">Grace Period</p><p> Grace period for data request in seconds</p></div><p>Missed data polling interval is an additional waiting time after receiving last reading + 5 minutes + grace period.<br> Used to avoid server lock if xDrip performs too frequent requests.</p><div class="admonition xdripitem"><p class="admonition-title">Missed data poll interval</p><p> Polling interval after missed data in minutes</p></div><br><h4 id="treatments" tabindex="-1">Treatments <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Treatments&quot;">​</a></h4><p>You can download treatments and receive notifications.</p><div class="admonition xdripitem"><p class="admonition-title">Finger BGs <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Download finger BGs from CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Boluses <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Download boluses from CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Meals <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Download meals from CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Notifications <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Download notifications from CareLink</p></div><br><h4 id="status-line" tabindex="-1">Status line <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Status line&quot;">​</a></h4><p>Sensor status and pump status can be enabled in the <a href="./../use/lesscommon.html#extra-status-line">Extra status line</a> option.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Settings<br>   Less Common settings<br>   Extra status line</p></div><div class="admonition xdripitem"><p class="admonition-title">External Status <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Display status from other apps like AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">Pump Status <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Display pump status information if available</p></div><p>Pump information (status, basal) is <u>only visible</u> in the status line and <strong>cannot be uploaded to Nightscout/Tidepool</strong>.</p><img src="'+a+'" style="zoom:75%;"><br><p>If no data is visible and no error message pops up you might need to <a href="./../use/startsensor.html#followers-and-companion-apps">Start sensor</a>.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',33)])])}const w=o(l,[["render",p]]);export{k as __pageData,w as default};
